#### Pattern 1: Simple Time-Based Batching

```csharp
public class SimpleKafkaBatchConsumer
{
    private readonly IConsumer<string, string> _consumer;
    private readonly int _batchSize;
    private readonly TimeSpan _batchTimeout;

    public async Task<List<ConsumeResult<string, string>>> ConsumeBatch(
        CancellationToken cancellationToken)
    {
        var batch = new List<ConsumeResult<string, string>>();
        var stopwatch = Stopwatch.StartNew();

        while (batch.Count < _batchSize &&
               stopwatch.Elapsed < _batchTimeout &&
               !cancellationToken.IsCancellationRequested)
        {
            try
            {
                var consumeResult = _consumer.Consume(
                    TimeSpan.FromMilliseconds(100));

                if (consumeResult != null)
                {
                    batch.Add(consumeResult);
                }
            }
            catch (ConsumeException ex)
            {
                // Log error and continue
            }
        }

        return batch;
    }
}
```

