#### Pattern 2: Channel-Based Batching (Recommended)

```csharp
using System.Threading.Channels;

public class ChannelBasedBatchConsumer
{
    private readonly IConsumer<string, string> _consumer;
    private readonly Channel<ConsumeResult<string, string>> _channel;
    private readonly int _batchSize;
    private readonly TimeSpan _batchTimeout;

    public ChannelBasedBatchConsumer(
        IConsumer<string, string> consumer,
        int batchSize = 100,
        TimeSpan? batchTimeout = null)
    {
        _consumer = consumer;
        _batchSize = batchSize;
        _batchTimeout = batchTimeout ?? TimeSpan.FromSeconds(1);

        // Bounded channel with backpressure
        _channel = Channel.CreateBounded<ConsumeResult<string, string>>(
            new BoundedChannelOptions(capacity: _batchSize * 10)
            {
                FullMode = BoundedChannelFullMode.Wait
            });
    }

    // Consumer thread: read from Kafka, write to channel
    public async Task ConsumeToChannel(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                var result = _consumer.Consume(cancellationToken);
                await _channel.Writer.WriteAsync(result, cancellationToken);
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (ConsumeException ex)
            {
                // Log and continue
            }
        }

        _channel.Writer.Complete();
    }

    // Processor thread: read from channel in batches
    public async IAsyncEnumerable<List<ConsumeResult<string, string>>> ReadBatches(
        [EnumeratorCancellation] CancellationToken cancellationToken)
    {
        while (await _channel.Reader.WaitToReadAsync(cancellationToken))
        {
            var batch = new List<ConsumeResult<string, string>>(_batchSize);
            var deadline = DateTime.UtcNow.Add(_batchTimeout);

            while (batch.Count < _batchSize && DateTime.UtcNow < deadline)
            {
                if (_channel.Reader.TryRead(out var item))
                {
                    batch.Add(item);
                }
                else
                {
                    await Task.Delay(10, cancellationToken);
                }
            }

            if (batch.Count > 0)
            {
                yield return batch;
            }
        }
    }
}
```

