#### Pattern 3: Adaptive Batch Sizing

```csharp
public class AdaptiveBatchConsumer
{
    private int _currentBatchSize;
    private readonly int _minBatchSize;
    private readonly int _maxBatchSize;
    private readonly SemaphoreSlim _semaphore;

    public AdaptiveBatchConsumer(
        int minBatchSize = 10,
        int maxBatchSize = 1000)
    {
        _minBatchSize = minBatchSize;
        _maxBatchSize = maxBatchSize;
        _currentBatchSize = minBatchSize;
        _semaphore = new SemaphoreSlim(1, 1);
    }

    public void AdjustBatchSize(TimeSpan processingTime, int messageCount)
    {
        _semaphore.Wait();
        try
        {
            // If processing is fast and we have headroom, increase batch size
            if (processingTime < TimeSpan.FromSeconds(1) &&
                _currentBatchSize < _maxBatchSize)
            {
                _currentBatchSize = Math.Min(
                    _currentBatchSize + 10,
                    _maxBatchSize);
            }
            // If processing is slow, decrease batch size
            else if (processingTime > TimeSpan.FromSeconds(5) &&
                     _currentBatchSize > _minBatchSize)
            {
                _currentBatchSize = Math.Max(
                    _currentBatchSize - 10,
                    _minBatchSize);
            }
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public int GetCurrentBatchSize() => _currentBatchSize;
}
```

