### Batch Processing Abstractions

```csharp
// Generic batch processor interface
public interface IBatchProcessor<T>
{
    Task<BatchProcessingResult> ProcessBatch(
        IReadOnlyList<T> batch,
        CancellationToken cancellationToken);
}

public record BatchProcessingResult
{
    public int SuccessCount { get; init; }
    public int FailureCount { get; init; }
    public List<BatchItemFailure> Failures { get; init; } = new();
}

public record BatchItemFailure
{
    public int Index { get; init; }
    public string ErrorMessage { get; init; }
    public Exception Exception { get; init; }
    public object Item { get; init; }
}

// Example: Database batch processor
public class DatabaseBatchProcessor : IBatchProcessor<ClaimMessage>
{
    private readonly IDbConnection _connection;

    public async Task<BatchProcessingResult> ProcessBatch(
        IReadOnlyList<ClaimMessage> batch,
        CancellationToken cancellationToken)
    {
        var result = new BatchProcessingResult();

        using var transaction = _connection.BeginTransaction();

        try
        {
            // Bulk insert using Dapper
            await _connection.ExecuteAsync(
                @"INSERT INTO Claims (Id, ClaimNumber, Amount, PatientId, CreatedDate)
                  VALUES (@Id, @ClaimNumber, @Amount, @PatientId, @CreatedDate)",
                batch,
                transaction);

            transaction.Commit();
            result.SuccessCount = batch.Count;
        }
        catch (Exception ex)
        {
            transaction.Rollback();

            // Fallback: process individually to identify failures
            result = await ProcessIndividually(batch, cancellationToken);
        }

        return result;
    }

    private async Task<BatchProcessingResult> ProcessIndividually(
        IReadOnlyList<ClaimMessage> batch,
        CancellationToken cancellationToken)
    {
        var result = new BatchProcessingResult();

        for (int i = 0; i < batch.Count; i++)
        {
            try
            {
                await ProcessSingle(batch[i], cancellationToken);
                result.SuccessCount++;
            }
            catch (Exception ex)
            {
                result.FailureCount++;
                result.Failures.Add(new BatchItemFailure
                {
                    Index = i,
                    ErrorMessage = ex.Message,
                    Exception = ex,
                    Item = batch[i]
                });
            }
        }

        return result;
    }
}
