### Phase 1: Configure Producer-Side Batching

Producer-side batching is automatically handled by Confluent.Kafka. Configure appropriately:

```csharp
// Program.cs - Producer configuration
using Confluent.Kafka;

var builder = WebApplication.CreateBuilder(args);

// Register Kafka producer with batching configuration
builder.Services.AddSingleton<IProducer<string, string>>(sp =>
{
    var config = new ProducerConfig
    {
        BootstrapServers = builder.Configuration["Kafka:BootstrapServers"],

        // Batching configuration
        LingerMs = 100,              // Accumulate for 100ms
        BatchSize = 32768,           // 32KB batches
        BatchNumMessages = 10000,    // Max 10k messages per batch

        // Compression
        CompressionType = CompressionType.Snappy,

        // Reliability
        Acks = Acks.All,
        EnableIdempotence = true,
        MaxInFlight = 5
    };

    return new ProducerBuilder<string, string>(config)
        .SetStatisticsHandler((producer, statistics) =>
        {
            // Log batching metrics
            var stats = JsonSerializer.Deserialize<ProducerStatistics>(statistics);
            Log.Information("Producer batch-size-avg: {AvgBatchSize}",
                stats?.BatchSizeAvg);
        })
        .Build();
});

var app = builder.Build();
app.Run();
```

