### Phase 2: Implement Consumer-Side Batch Collection

Use Channel-based approach for efficient batch collection:

```csharp
// Services/KafkaBatchConsumerService.cs
using System.Threading.Channels;
using Confluent.Kafka;

public class KafkaBatchConsumerService : BackgroundService
{
    private readonly IConsumer<string, string> _consumer;
    private readonly IBatchProcessor<ClaimMessage> _batchProcessor;
    private readonly ILogger<KafkaBatchConsumerService> _logger;
    private readonly Channel<ConsumeResult<string, string>> _channel;
    private readonly BatchConfiguration _config;

    public KafkaBatchConsumerService(
        IConsumer<string, string> consumer,
        IBatchProcessor<ClaimMessage> batchProcessor,
        ILogger<KafkaBatchConsumerService> logger,
        IOptions<BatchConfiguration> config)
    {
        _consumer = consumer;
        _batchProcessor = batchProcessor;
        _logger = logger;
        _config = config.Value;

        // Create bounded channel with backpressure
        _channel = Channel.CreateBounded<ConsumeResult<string, string>>(
            new BoundedChannelOptions(_config.ChannelCapacity)
            {
                FullMode = BoundedChannelFullMode.Wait
            });
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _consumer.Subscribe("claims-topic");

        // Start consumer and processor tasks
        var consumerTask = ConsumeToChannelAsync(stoppingToken);
        var processorTask = ProcessBatchesAsync(stoppingToken);

        await Task.WhenAll(consumerTask, processorTask);
    }

    private async Task ConsumeToChannelAsync(CancellationToken cancellationToken)
    {
        try
        {
            while (!cancellationToken.IsCancellationRequested)
            {
                try
                {
                    var consumeResult = _consumer.Consume(cancellationToken);

                    if (consumeResult != null)
                    {
                        await _channel.Writer.WriteAsync(consumeResult, cancellationToken);
                    }
                }
                catch (ConsumeException ex)
                {
                    _logger.LogError(ex, "Error consuming message");
                }
            }
        }
        finally
        {
            _channel.Writer.Complete();
            _consumer.Close();
        }
    }

    private async Task ProcessBatchesAsync(CancellationToken cancellationToken)
    {
        await foreach (var batch in CollectBatches(cancellationToken))
        {
            await ProcessBatch(batch, cancellationToken);
        }
    }

    private async IAsyncEnumerable<List<ConsumeResult<string, string>>> CollectBatches(
        [EnumeratorCancellation] CancellationToken cancellationToken)
    {
        var batch = new List<ConsumeResult<string, string>>(_config.BatchSize);
        var batchTimeout = TimeSpan.FromSeconds(_config.BatchTimeoutSeconds);

        while (await _channel.Reader.WaitToReadAsync(cancellationToken))
        {
            var deadline = DateTime.UtcNow.Add(batchTimeout);

            while (batch.Count < _config.BatchSize && DateTime.UtcNow < deadline)
            {
                if (_channel.Reader.TryRead(out var item))
                {
                    batch.Add(item);
                }
                else
                {
                    // Wait briefly before checking again
                    await Task.Delay(10, cancellationToken);
                }
            }

            if (batch.Count > 0)
            {
                yield return batch;
                batch = new List<ConsumeResult<string, string>>(_config.BatchSize);
            }
        }

        // Return remaining items in final batch
        if (batch.Count > 0)
        {
            yield return batch;
        }
    }

    private async Task ProcessBatch(
        List<ConsumeResult<string, string>> batch,
        CancellationToken cancellationToken)
    {
        var stopwatch = Stopwatch.StartNew();

        try
        {
            _logger.LogInformation("Processing batch of {Count} messages", batch.Count);

            // Deserialize messages
            var messages = batch
                .Select(cr => JsonSerializer.Deserialize<ClaimMessage>(cr.Message.Value))
                .ToList();

            // Process batch
            var result = await _batchProcessor.ProcessBatch(messages, cancellationToken);

            stopwatch.Stop();

            // Log results
            _logger.LogInformation(
                "Batch processed: {Success} succeeded, {Failed} failed in {ElapsedMs}ms",
                result.SuccessCount, result.FailureCount, stopwatch.ElapsedMilliseconds);

            // Handle partial failures
            if (result.FailureCount > 0)
            {
                await HandleBatchFailures(result.Failures, cancellationToken);
            }

            // Commit offsets only after successful processing
            var lastOffset = batch.Last().TopicPartitionOffset;
            _consumer.Commit(lastOffset);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing batch of {Count} messages", batch.Count);

            // Don't commit offset - messages will be reprocessed
            // Consider implementing retry logic or dead letter queue
        }
    }

    private async Task HandleBatchFailures(
        List<BatchItemFailure> failures,
        CancellationToken cancellationToken)
    {
        foreach (var failure in failures)
        {
            _logger.LogWarning(
                "Failed to process item at index {Index}: {Error}",
                failure.Index, failure.ErrorMessage);

            // Send to dead letter queue or retry mechanism
            // await _deadLetterProducer.ProduceAsync(failure.Item, cancellationToken);
        }
    }
}

public class BatchConfiguration
{
    public int BatchSize { get; set; } = 100;
    public int BatchTimeoutSeconds { get; set; } = 5;
    public int ChannelCapacity { get; set; } = 10000;
}
```

