### Phase 3: Implement Batch Processing Logic

```csharp
// Services/ClaimBatchProcessor.cs
using Dapper;

public class ClaimBatchProcessor : IBatchProcessor<ClaimMessage>
{
    private readonly IDbConnection _connection;
    private readonly ILogger<ClaimBatchProcessor> _logger;

    public ClaimBatchProcessor(
        IDbConnection connection,
        ILogger<ClaimBatchProcessor> logger)
    {
        _connection = connection;
        _logger = logger;
    }

    public async Task<BatchProcessingResult> ProcessBatch(
        IReadOnlyList<ClaimMessage> batch,
        CancellationToken cancellationToken)
    {
        try
        {
            // Attempt bulk insert
            return await BulkInsert(batch, cancellationToken);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Bulk insert failed, falling back to individual processing");

            // Fallback: process individually to identify failures
            return await ProcessIndividually(batch, cancellationToken);
        }
    }

    private async Task<BatchProcessingResult> BulkInsert(
        IReadOnlyList<ClaimMessage> batch,
        CancellationToken cancellationToken)
    {
        using var transaction = _connection.BeginTransaction();

        try
        {
            // Bulk insert using Dapper
            var insertedCount = await _connection.ExecuteAsync(
                @"INSERT INTO Claims (Id, ClaimNumber, Amount, PatientId, ServiceDate, Status, CreatedDate)
                  VALUES (@Id, @ClaimNumber, @Amount, @PatientId, @ServiceDate, @Status, @CreatedDate)",
                batch,
                transaction);

            transaction.Commit();

            _logger.LogInformation("Bulk inserted {Count} claims", insertedCount);

            return new BatchProcessingResult
            {
                SuccessCount = insertedCount,
                FailureCount = 0
            };
        }
        catch
        {
            transaction.Rollback();
            throw;
        }
    }

    private async Task<BatchProcessingResult> ProcessIndividually(
        IReadOnlyList<ClaimMessage> batch,
        CancellationToken cancellationToken)
    {
        var result = new BatchProcessingResult();

        for (int i = 0; i < batch.Count; i++)
        {
            try
            {
                await ProcessSingleClaim(batch[i], cancellationToken);
                result.SuccessCount++;
            }
            catch (Exception ex)
            {
                result.FailureCount++;
                result.Failures.Add(new BatchItemFailure
                {
                    Index = i,
                    ErrorMessage = ex.Message,
                    Exception = ex,
                    Item = batch[i]
                });

                _logger.LogError(ex,
                    "Failed to process claim {ClaimNumber} at index {Index}",
                    batch[i].ClaimNumber, i);
            }
        }

        return result;
    }

    private async Task ProcessSingleClaim(
        ClaimMessage claim,
        CancellationToken cancellationToken)
    {
        await _connection.ExecuteAsync(
            @"INSERT INTO Claims (Id, ClaimNumber, Amount, PatientId, ServiceDate, Status, CreatedDate)
              VALUES (@Id, @ClaimNumber, @Amount, @PatientId, @ServiceDate, @Status, @CreatedDate)",
            claim);
    }
}

public record ClaimMessage
{
    public Guid Id { get; init; }
    public string ClaimNumber { get; init; }
    public decimal Amount { get; init; }
    public Guid PatientId { get; init; }
    public DateTime ServiceDate { get; init; }
    public string Status { get; init; }
    public DateTime CreatedDate { get; init; }
}
```

