        _processingFailures = _meter.CreateCounter<long>(
            "processing_failures_total",
            description: "Total number of processing failures");

        _batchSize = _meter.CreateHistogram<double>(
            "batch_size",
            description: "Distribution of batch sizes");

        _processingTime = _meter.CreateHistogram<double>(
            "batch_processing_time_ms",
            description: "Batch processing time in milliseconds");
    }

    public void RecordBatchProcessed(
        int batchSize,
        int successCount,
        int failureCount,
        TimeSpan processingTime)
    {
        _batchesProcessed.Add(1);
        _messagesProcessed.Add(successCount);
        _processingFailures.Add(failureCount);
        _batchSize.Record(batchSize);
        _processingTime.Record(processingTime.TotalMilliseconds);
    }
}

// Usage in batch processor
public class ObservableClaimBatchProcessor : IBatchProcessor<ClaimMessage>
{
    private readonly IBatchProcessor<ClaimMessage> _innerProcessor;
    private readonly BatchProcessingMetrics _metrics;

    public async Task<BatchProcessingResult> ProcessBatch(
        IReadOnlyList<ClaimMessage> batch,
        CancellationToken cancellationToken)
    {
        var stopwatch = Stopwatch.StartNew();

        var result = await _innerProcessor.ProcessBatch(batch, cancellationToken);

        stopwatch.Stop();

        _metrics.RecordBatchProcessed(
            batch.Count,
            result.SuccessCount,
            result.FailureCount,
            stopwatch.Elapsed);

        return result;
    }
}
