### Phase 5: Implement Adaptive Batch Sizing

```csharp
// Services/AdaptiveBatchSizeManager.cs
public class AdaptiveBatchSizeManager
{
    private readonly int _minBatchSize;
    private readonly int _maxBatchSize;
    private int _currentBatchSize;
    private readonly TimeSpan _targetProcessingTime;
    private readonly SemaphoreSlim _lock = new(1, 1);
    private readonly ILogger<AdaptiveBatchSizeManager> _logger;

    public AdaptiveBatchSizeManager(
        int minBatchSize = 10,
        int maxBatchSize = 1000,
        TimeSpan? targetProcessingTime = null,
        ILogger<AdaptiveBatchSizeManager> logger = null)
    {
        _minBatchSize = minBatchSize;
        _maxBatchSize = maxBatchSize;
        _currentBatchSize = minBatchSize;
        _targetProcessingTime = targetProcessingTime ?? TimeSpan.FromSeconds(2);
        _logger = logger;
    }

    public async Task<int> GetBatchSize()
    {
        await _lock.WaitAsync();
        try
        {
            return _currentBatchSize;
        }
        finally
        {
            _lock.Release();
        }
    }

    public async Task AdjustBatchSize(TimeSpan actualProcessingTime, int messageCount)
    {
        await _lock.WaitAsync();
        try
        {
            var previousSize = _currentBatchSize;

            // Processing is faster than target - increase batch size
            if (actualProcessingTime < _targetProcessingTime * 0.5 &&
                _currentBatchSize < _maxBatchSize)
            {
                var increment = Math.Max(1, _currentBatchSize / 10);
                _currentBatchSize = Math.Min(_currentBatchSize + increment, _maxBatchSize);
            }
            // Processing is slower than target - decrease batch size
            else if (actualProcessingTime > _targetProcessingTime * 1.5 &&
                     _currentBatchSize > _minBatchSize)
            {
                var decrement = Math.Max(1, _currentBatchSize / 10);
                _currentBatchSize = Math.Max(_currentBatchSize - decrement, _minBatchSize);
            }

            if (_currentBatchSize != previousSize)
            {
                _logger?.LogInformation(
                    "Adjusted batch size from {Previous} to {Current} " +
                    "(processing time: {ProcessingTime}ms for {Count} messages)",
                    previousSize, _currentBatchSize,
                    actualProcessingTime.TotalMilliseconds, messageCount);
            }
        }
        finally
        {
            _lock.Release();
        }
    }
}

// Integration with consumer
