### Example: High-Throughput Batch Producer

```csharp
// Services/HighThroughputProducerService.cs
public class HighThroughputProducerService
{
    private readonly IProducer<string, string> _producer;
    private readonly ILogger<HighThroughputProducerService> _logger;

    public async Task ProduceClaimBatch(
        IEnumerable<ClaimMessage> claims,
        CancellationToken cancellationToken)
    {
        var tasks = new List<Task>();

        foreach (var claim in claims)
        {
            var message = new Message<string, string>
            {
                Key = claim.ClaimNumber,
                Value = JsonSerializer.Serialize(claim),
                Headers = new Headers
                {
                    { "event-type", Encoding.UTF8.GetBytes("claim-created") },
                    { "timestamp", BitConverter.GetBytes(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()) }
                }
            };

            // Fire and forget (batching happens automatically)
            var task = _producer.ProduceAsync("claims-topic", message, cancellationToken)
                .ContinueWith(result =>
                {
                    if (result.IsFaulted)
                    {
                        _logger.LogError(result.Exception,
                            "Failed to produce message for claim {ClaimNumber}",
                            claim.ClaimNumber);
                    }
                }, cancellationToken);

            tasks.Add(task);
        }

        // Wait for all to complete
        await Task.WhenAll(tasks);

        // Flush to ensure all messages are sent
        _producer.Flush(TimeSpan.FromSeconds(10));
    }
}
