```csharp
// Services/ParallelBatchProcessor.cs
public class ParallelBatchProcessor : IBatchProcessor<ClaimMessage>
{
    private readonly ILogger<ParallelBatchProcessor> _logger;
    private readonly int _maxDegreeOfParallelism;

    public ParallelBatchProcessor(
        ILogger<ParallelBatchProcessor> logger,
        IConfiguration configuration)
    {
        _logger = logger;
        _maxDegreeOfParallelism = configuration
            .GetValue<int>("Performance:MaxDegreeOfParallelism", 4);
    }

    public async Task<BatchProcessingResult> ProcessBatch(
        IReadOnlyList<ClaimMessage> batch,
        CancellationToken cancellationToken)
    {
        var result = new BatchProcessingResult();
        var lockObj = new object();

        await Parallel.ForEachAsync(
            batch.Select((claim, index) => (claim, index)),
            new ParallelOptions
            {
                MaxDegreeOfParallelism = _maxDegreeOfParallelism,
                CancellationToken = cancellationToken
            },
            async (item, ct) =>
            {
                try
                {
                    await ProcessSingleClaim(item.claim, ct);

                    lock (lockObj)
                    {
                        result.SuccessCount++;
                    }
                }
                catch (Exception ex)
                {
                    lock (lockObj)
                    {
                        result.FailureCount++;
                        result.Failures.Add(new BatchItemFailure
                        {
                            Index = item.index,
                            ErrorMessage = ex.Message,
                            Exception = ex,
                            Item = item.claim
                        });
                    }
                }
            });

        return result;
    }

    private async Task ProcessSingleClaim(
        ClaimMessage claim,
        CancellationToken cancellationToken)
    {
        // Process individual claim
        await Task.Delay(10, cancellationToken); // Simulate processing
    }
}
